#!/usr/bin/env bash
# setup.sh — 一次性配置 NJU HPC 自动化套件
# AI 代理运行本脚本；需要用户回答的问题都带默认值。
set -euo pipefail

KIT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONF="$KIT_DIR/hpc.conf"
SSH_CONFIG="$HOME/.ssh/config"
KEY_FILE="$HOME/.ssh/id_ed25519"
SSH_ALIAS='nju-hpc'
SSH_ALIAS_ENTRY='nju-hpc-entry'

ask() {  # ask <prompt> <default>
    local prompt="$1" default="$2" reply
    read -r -p "$prompt [$default]: " reply || true
    printf '%s' "${reply:-$default}"
}

write_conf() {  # write_conf <login_ip> <userland_port>
    cat > "$CONF" <<EOF
# Generated by setup.sh on $(date -Is)
HPC_USER='$HPC_USER'
LOGIN_NODE='$LOGIN_NODE'
LOGIN_IP='${1:-}'
USERLAND_PORT='${2:-}'
ENTRY_HOST='$ENTRY_HOST'
GATEWAY_DEST='$GATEWAY_DEST'
SSH_ALIAS='nju-hpc'
SSH_ALIAS_ENTRY='nju-hpc-entry'
KEY_FILE='$KEY_FILE'
KIT_DIR='$KIT_DIR'
EOF
    chmod 600 "$CONF"
}

update_direct_alias() {  # 创建/更新直连别名块: $1=ip $2=port
    local ip="$1" port="$2" tmp
    [ -n "$ip" ] && [ -n "$port" ] || return 0
    tmp="$(mktemp)"
    awk -v alias="Host $SSH_ALIAS" \
        -v block="Host $SSH_ALIAS\n  HostName $ip\n  Port $port\n  User $HPC_USER\n  IdentityFile $KEY_FILE" '
        $0 == alias { print block; skip=1; next }
        /^Host / { skip=0 }
        !skip { print }
    ' "$SSH_CONFIG" > "$tmp" && cat "$tmp" > "$SSH_CONFIG" && rm -f "$tmp"
    if ! grep -q "^Host $SSH_ALIAS\$" "$SSH_CONFIG" 2>/dev/null; then
        printf '\n%s\n  HostName %s\n  Port %s\n  User %s\n  IdentityFile %s\n' \
            "Host $SSH_ALIAS" "$ip" "$port" "$HPC_USER" "$KEY_FILE" >> "$SSH_CONFIG"
    fi
}

echo "== NJU HPC kit setup =="
HPC_USER=""
while [ -z "$HPC_USER" ]; do
    HPC_USER="$(ask "集群用户名（必填，如 abc123）" "")"
done
LOGIN_NODE="$(ask "登录节点" "login2")"
ENTRY_HOST="$(ask "双认证网关" "entry.nju.edu.cn")"
# 网关用户名需要目标节点编码（格式：用户/目标内网地址/self），
# 否则网关拒绝执行请求（exec request failed）。
GATEWAY_DEST="$(ask "网关目标节点内网地址（login2=10.1.0.102）" "10.1.0.102")"
# 用户态 sshd 端口无需配置：首次连接时由 ensure-userland.sh 在登录节点
# 自动选择空闲高位端口（20000–59999 随机），并回写到本文件。

mkdir -p "$HOME/.ssh" && chmod 700 "$HOME/.ssh"
if [ ! -f "$KEY_FILE" ]; then
    ssh-keygen -t ed25519 -N '' -f "$KEY_FILE" -q
    echo "-> 生成本机密钥 $KEY_FILE"
fi

# 重跑 setup 时保留已有的回填状态（IP/端口），避免清空已配置信息
prev_ip=""
prev_port=""
if [ -f "$CONF" ]; then
    prev_ip="$(grep -o "^LOGIN_IP='[^']*'" "$CONF" 2>/dev/null | sed "s/^LOGIN_IP='//;s/'\$//" || true)"
    prev_port="$(grep -o "^USERLAND_PORT='[^']*'" "$CONF" 2>/dev/null | sed "s/^USERLAND_PORT='//;s/'\$//" || true)"
fi

write_conf "$prev_ip" "$prev_port"
echo "-> wrote $CONF"

# 安装用户级 skill（新对话自动发现本套件）
SKILL_DIR="$HOME/.agents/skills/nju-hpc"
if [ -f "$KIT_DIR/skill/SKILL.md" ]; then
    mkdir -p "$SKILL_DIR"
    ln -sfn "$KIT_DIR/skill/SKILL.md" "$SKILL_DIR/SKILL.md" 2>/dev/null || true
    if [ -L "$SKILL_DIR/SKILL.md" ]; then
        echo "-> skill 已安装（符号链接，随 git pull 自动更新）: $SKILL_DIR"
    else
        cp "$KIT_DIR/skill/SKILL.md" "$SKILL_DIR/SKILL.md"
        echo "-> skill 已安装（本机不支持符号链接，为拷贝；git pull 后重跑 setup.sh 刷新）: $SKILL_DIR"
    fi
fi

touch "$SSH_CONFIG"; chmod 600 "$SSH_CONFIG"
if ! grep -q "Host $SSH_ALIAS_ENTRY" "$SSH_CONFIG" 2>/dev/null; then
    cat >> "$SSH_CONFIG" <<EOF

Host $SSH_ALIAS_ENTRY
  HostName $ENTRY_HOST
  User $HPC_USER/$GATEWAY_DEST/self
EOF
    echo "-> ssh config 已追加网关别名 $SSH_ALIAS_ENTRY"
    echo "  （直连别名 $SSH_ALIAS 将在首次连接后由自愈回填自动创建）"
else
    echo "-> ssh config 网关别名已存在，跳过"
fi

echo
echo "== 网络环境确认 =="
cat <<'EOF'
是否已处于校内网 / 已连接可访问校园资源的 VPN？
  y) 是 —— 接下来请你输入一次集群密码，之后自动完成：
        公钥安装 + 用户态 sshd 部署 + 免密直连（campus 模式，断线自动重连）。
  n) 否 —— 跳过；之后首次 start-session.sh 时会引导做一次
        密码 + 两步认证，并在认证后自动完成上述部署。
EOF
read -r -p "校内网环境? (y/n) [n]: " oncampus || oncampus="n"

if [ "$oncampus" = "y" ]; then
    echo "首次登录需要密码（仅一次）..."
    target="$HPC_USER@$LOGIN_NODE"
    if ssh -o PreferredAuthentications=password,keyboard-interactive "$target" true 2>/dev/null; then
        pub="$(base64 -w0 "$KEY_FILE.pub")"
        out="$(ssh "$target" "PUB_B64='$pub' PORT='' bash -s" < "$KIT_DIR/ensure-userland.sh")"
        printf '%s\n' "$out"
        newport="$(printf '%s\n' "$out" | sed -n 's/.*USERLAND_OK port=\([0-9][0-9]*\).*/\1/p' | tail -1)"
        ip="$(ssh "$target" 'hostname -I' | tr ' ' '\n' | grep -E '^210\.28\.' | head -1)"
        if [ -n "$ip" ] && [ -n "$newport" ]; then
            write_conf "$ip" "$newport"
            update_direct_alias "$ip" "$newport"
            echo "-> campus 模式就绪：$HPC_USER@$ip:$newport（免密）"
        fi
    else
        if getent hosts "$LOGIN_NODE" >/dev/null 2>&1; then
            echo "!! 直连登录失败（密码错误或网络受限）。" >&2
        else
            echo "!! 节点名 $LOGIN_NODE 无法解析（VPN/校外环境属正常现象）。" >&2
        fi
        echo "   改走校外网路径：bash $KIT_DIR/start-session.sh" >&2
        echo "   （完成密码+两步认证后，会自动部署免密直连并回填配置。）" >&2
    fi
else
    echo "-> 跳过免密配置（校外网模式）。首次使用请先运行 start-session.sh"
    echo "  （认证成功后会自动选择端口、部署用户态 sshd 并回填本机配置。）"
fi

echo
echo "== 冒烟测试 =="
bash "$KIT_DIR/detect-net.sh" || true
echo
echo "setup 完成。日常使用：bash $KIT_DIR/run-session.sh 'hostname'"
